        "extensions": [
          "md",
          "mdc"
        ],
        "linebreakArgument": "--markdown-linebreak-ext=md,mdc"
      }
    }
  },
  "dependabot": {
    "version": 2,
    "updates": [
      {
        "package-ecosystem": "github-actions",
        "directory": "/",
        "schedule": {
          "interval": "weekly"
        }
      }
