ersionExit\"\n}\nWrite-Host \"Node executable: $strNodePath ($strNodeVersion)\"\nWrite-Host \"npm executable: $strNpmPath ($strNpmVersion)\"\n\n# Reviewed baseline. The before/after comparison further below proves\n# only that npm ci left these files alone; it cannot detect metadata\n# that was already altered at review time. This gate runs before\n# installation so unreviewed scripts are never installed and never run.\n$strReviewedPackageHash = '59E676D981CFFA350CB72E7EA4B1AEEC2C49D56621958A095AA0E76733EC2CD9'\n$strReviewedLockHash = '5EFC1286025CDC3AD03796C5F4E44CC697E674A30E61DE05E299B2A30ABAD1A2'\n$strPackageBefore = (Get-FileHash -LiteralPath package.json -Algorithm SHA256).Hash\n$strLockBefore = (Get-FileHash -LiteralPath package-lock.json -Algorithm SHA256).Hash\nif ($strPackageBefore -cne $strReviewedPackageHash -or $strLockBefore -cne $strReviewedLockHash) {\n    throw 'supply: package metadata does not match the reviewed supply digest'\n}\n\n# npm reads .npmrc from the project directory before it runs anything,\n# and script-shell there replaces the interpreter for every npm run. A\n# pull request can add one without altering either reviewed digest or\n# any governed workflow, after which both lint phases exit zero with the\n# command echoed and no linter ever executed. No .npmrc is reviewed in\n# this repository, so any is refused here, ahead of installation, so npm\n# never reads one.\nforeach ($strNpmConfigPath in @('.npmrc', '../.npmrc', '../../.npmrc')) {\n    if (Test-Path -LiteralPath $strNpmConfigPath) {\n        throw 'supply: repository-controlled npm configuration is present'\n    }\n}\n\n# The loop above walks project paths, which is where a committed\n# .npmrc would sit -- but npm also loads a per-user file at\n# $HOME/.npmrc and a global one, and neither is under the repository\n# tree. A script-shell setting in either replaces the interpreter for\n# every npm run, so both lint phases would exit zero with the command\n# echoed and no linter e